import{_ as t,o as a,c as i,a2 as d}from"./chunks/framework.AuRYXM_l.js";const u=JSON.parse('{"title":"Chainy pre-final recovery plan","description":"Original planning date: October 5, 2026; revised local forecast: October 8, 2026 (see final section). Confirmed pre-final defense: November 21, 2026, requiring 60 percent; the","frontmatter":{"title":"Chainy pre-final recovery plan","description":"Original planning date: October 5, 2026; revised local forecast: October 8, 2026 (see final section). Confirmed pre-final defense: November 21, 2026, requiring 60 percent; the","source":"docs/kanban-plan-draft.md","category":"Delivery & team","sourceUpdated":"2026-10-08T06:33:54+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/kanban-plan-draft.md","filePath":"content/docs/kanban-plan-draft.md"}'),r={name:"content/docs/kanban-plan-draft.md"};function n(o,e,s,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[d('<div><h1 id="chainy-pre-final-recovery-plan">Chainy pre-final recovery plan<a class="header-anchor" href="#chainy-pre-final-recovery-plan" aria-label="Link to this section">​</a></h1><p>Original planning date: October 5, 2026; revised local forecast: October 8, 2026 (see final section). Confirmed pre-final defense: November 21, 2026, requiring 60 percent; the supplied 32-point rubric lacks actual criterion names and does not define completion. There are 47 elapsed calendar days between those dates. User reports zero implementation progress. This is a conditional recovery forecast, not an approved claim that the schedule is feasible.</p><p>The <a href="/Chainy-Docs/content/docs/archive/kanban-plan-2026-10-05.html">previous 29-card plan</a> is preserved with original IDs, owners, statuses and dates. The broader September 2026–April 2027 cycle remains. Old milestone dates do not prove delivery, and this proposed recovery plan does not change school deadlines.</p><h2 id="delivery-recommendation">Delivery recommendation<a class="header-anchor" href="#delivery-recommendation" aria-label="Link to this section">​</a></h2><p>Retain free construction, three-node simulation, local example-based classification, and an agent challenge, but implement small bounded versions. Prefer placeholders and reusable assets until the learning loop works. Avoid a custom backend, teacher web dashboard, microphone features, expansive worlds, and extra reward systems before pre-final.</p><p>Do not claim that two of three levels equals 60 percent. The rubric must determine that calculation. The provisional target below demonstrates every required concept at limited scale, with one fully validated vertical slice first.</p><h2 id="previous-october-5-checkpoints-superseded-local-forecast">Previous October 5 checkpoints (superseded local forecast)<a class="header-anchor" href="#previous-october-5-checkpoints-superseded-local-forecast" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Target</th><th>Required evidence</th></tr></thead><tbody><tr><td>October 7–11</td><td>Rubric/capacity, named owners, scoped objectives, linked game repo, first device APK, SQLite/export spike</td></tr><tr><td>October 18</td><td>Complete level 1 loop; classifier prototype; pilot protocol ready or blocker explicit</td></tr><tr><td>October 25</td><td>Level 2 and local node simulation; reusable art kit; teacher export/import</td></tr><tr><td>November 1</td><td>AI level and bounded agent puzzle</td></tr><tr><td>November 6</td><td>Integrated three-level build and feature freeze</td></tr><tr><td>November 7–13</td><td>Integrated pilot-readiness check by Nov 7; required approved pilot evidence Nov 8–13; continuing regression</td></tr><tr><td>November 16</td><td>Manuscript and evidence package finalized to the available actual results</td></tr><tr><td>November 17–20</td><td>Critical fixes, offline rehearsals and backup preparation</td></tr><tr><td>November 21</td><td>Pre-final defense</td></tr></tbody></table><p>Actual learner scheduling is a critical dependency, not a task to leave until November. Research preparation and manuscript writing begin early; final QA waits for an integrated build. If the first Android/SQLite spike fails by October 11, revise the forecast immediately. If level 1 is not complete by October 18, reduce content/art quantity and seek adviser agreement on the defense scope; do not keep all dates by assertion.</p><h2 id="executable-backlog">Executable backlog<a class="header-anchor" href="#executable-backlog" aria-label="Link to this section">​</a></h2><p>The table preserves original published target dates; use the revised forecast below for local planning. Dates here are not newly synchronized to GitHub/Trello. Tasks are delegated by name in Lead, Support and Task reviewer fields; GitHub accounts are not required. Status is Todo for implementation work. Scope recommendations are flagged inside the tasks. <a href="/Chainy-Docs/attachments/docs/backlog.json">Machine-readable backlog</a> contains descriptions and acceptance checks.</p><table><thead><tr><th>ID</th><th>Deliverable</th><th>Target</th><th>Blocked by</th><th>Requirements</th></tr></thead><tbody><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/2">CH-01</a></td><td>Confirm defense rubric and team capacity</td><td>2026-10-07</td><td>None</td><td>CH-R12</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/3">CH-02</a></td><td>Freeze bounded mechanics and learning objectives</td><td>2026-10-09</td><td>CH-01</td><td>CH-R02, CH-R03, CH-R04, CH-R05, CH-R06, CH-R07, CH-R08</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/4">CH-03</a></td><td>Link game repository and produce first Android APK</td><td>2026-10-09</td><td>None</td><td>CH-R01, CH-R09</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/5">CH-04</a></td><td>Validate SQLite and Android export integration</td><td>2026-10-11</td><td>CH-03</td><td>CH-R09, CH-R10, CH-R11</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/6">CH-05</a></td><td>Build shared exploration and free construction loop</td><td>2026-10-16</td><td>CH-02, CH-03</td><td>CH-R01, CH-R02</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/7">CH-06</a></td><td>Deliver level 1 ordering vertical slice</td><td>2026-10-18</td><td>CH-04, CH-05, CH-26</td><td>CH-R03, CH-R08, CH-R09</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/8">CH-07</a></td><td>Deliver tamper detection and three-node simulation</td><td>2026-10-25</td><td>CH-06</td><td>CH-R04, CH-R05</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/9">CH-08</a></td><td>Prototype example-trained local classifier</td><td>2026-10-18</td><td>CH-02, CH-03</td><td>CH-R06</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/10">CH-09</a></td><td>Integrate AI level and short agent challenge</td><td>2026-11-01</td><td>CH-05, CH-08</td><td>CH-R06, CH-R07, CH-R08</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/11">CH-10</a></td><td>Produce reusable teen-oriented art and interface</td><td>2026-10-25</td><td>CH-02, CH-03</td><td>CH-R01, CH-R08</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/12">CH-11</a></td><td>Implement teacher export and duplicate-safe aggregation</td><td>2026-10-25</td><td>CH-04</td><td>CH-R10</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/13">CH-12</a></td><td>Approve pilot protocol and evidence handling</td><td>2026-10-18</td><td>CH-01, CH-02, CH-23, CH-24</td><td>CH-R08, CH-R10, CH-R12</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/14">CH-13</a></td><td>Integrate three levels and freeze new features</td><td>2026-11-06</td><td>CH-07, CH-09, CH-10, CH-11, CH-26</td><td>CH-R01, CH-R02, CH-R03, CH-R04, CH-R05, CH-R06, CH-R07, CH-R08, CH-R09, CH-R10</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/15">CH-14</a></td><td>Verify pilot-ready build and update recovery</td><td>2026-11-07</td><td>CH-13</td><td>CH-R01, CH-R09, CH-R10, CH-R11</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/16">CH-15</a></td><td>Run approved pilot and collect required pre-final evidence</td><td>2026-11-13</td><td>CH-12, CH-14</td><td>CH-R08, CH-R10, CH-R12</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/17">CH-16</a></td><td>Finalize manuscript formatting and defense evidence</td><td>2026-11-16</td><td>CH-01, CH-22, CH-23, CH-25</td><td>CH-R12</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/18">CH-17</a></td><td>Rehearse and package pre-final demonstration</td><td>2026-11-20</td><td>CH-14, CH-15, CH-16</td><td>CH-R12</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/19">CH-18</a></td><td>Resolve pre-final panel feedback and rebaseline</td><td>2026-11-27</td><td>CH-17</td><td>CH-R12</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/20">CH-19</a></td><td>Complete approved learner evaluation and QA evidence</td><td>2026-12-18</td><td>CH-18, CH-12</td><td>CH-R08, CH-R10, CH-R12</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/21">CH-20</a></td><td>Finalize release package and manuscript</td><td>2027-02-08</td><td>CH-19</td><td>CH-R11, CH-R12</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/22">CH-21</a></td><td>Complete final defense and project handover</td><td>2027-04-09</td><td>CH-20</td><td>CH-R12</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/24">CH-22</a></td><td>Complete manuscript Chapters I and II with verified sources</td><td>2026-10-14</td><td>CH-02</td><td>CH-R12</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/25">CH-23</a></td><td>Complete Chapter III and approved evaluation instruments</td><td>2026-10-16</td><td>CH-01, CH-02</td><td>CH-R08, CH-R10, CH-R12</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/26">CH-24</a></td><td>Secure pilot-area documents and learner-session booking</td><td>2026-10-12</td><td>CH-01</td><td>CH-R10, CH-R12</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/27">CH-25</a></td><td>Write results conclusions and assemble official appendices</td><td>2026-11-16</td><td>CH-15, CH-23</td><td>CH-R12</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/28">CH-26</a></td><td>Implement readable menus HUD and teacher-facing screens</td><td>2026-10-16</td><td>CH-02, CH-03</td><td>CH-R01, CH-R08, CH-R09, CH-R10</td></tr></tbody></table><p>Writing starts in CH-22/23; CH-25 produces the results/conclusions and appendices. CH-16 consolidates them. CH-17 requires mandatory pilot evidence and the complete manuscript. Missing required evidence remains a blocker, not a completed gap report.</p><h2 id="board-operating-rules">Board operating rules<a class="header-anchor" href="#board-operating-rules" aria-label="Link to this section">​</a></h2><p>Use the <a href="https://github.com/orgs/Kamiyon-Studio/projects/5">private delivery board</a>, linked to both repositories. Repository documents define requirements and decisions; issues track execution. The <a href="https://trello.com/b/VPH0LHFN/capstone-t13">Trello team board</a> synchronizes the 26 linked tasks so members can move cards, edit title/description and add comments without GitHub accounts. See <a href="/Chainy-Docs/content/tools/kanban-sync/readme.html">sync behavior and limits</a>. Board states: Todo, In Progress, Done; represent blockers in issue dependencies and text. A card is Done only when its acceptance evidence is linked, not when code is merely written.</p><p>Limit each person to one active implementation card where practical. Shared prerequisites and scarce skills constrain parallel work. Do not infer interchangeable available capacity from five team members or AI model access. Original source cards remain historical; CH IDs are the new recovery plan and must not silently replace their meaning.</p><p>External publication status and exact issue URLs are maintained in <a href="/Chainy-Docs/attachments/docs/backlog.json">backlog.json</a>. No participant records, identity maps or credentials belong in issues.</p><h2 id="team-delegation">Team delegation<a class="header-anchor" href="#team-delegation" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Person</th><th>Confirmed role</th><th>Proposed delivery responsibility</th></tr></thead><tbody><tr><td>Sherwin Limosnero</td><td>Project lead</td><td>Scope, site coordination, AI prototype/level, external evidence importer and defense coordination</td></tr><tr><td>Christian Jude Villaber</td><td>Technical lead</td><td>Build/toolchain, SQLite/device export, construction/blockchain systems, integration and technical QA review</td></tr><tr><td>Sean Matthew Narvaez</td><td>Documentation lead</td><td>Protocol, manuscript, evidence management and pilot coordination</td></tr><tr><td>Luis Cabrido III</td><td>Art lead</td><td>Reusable mobile asset kit and art budget</td></tr><tr><td>Miguel De Leon</td><td>UI and documentation support</td><td>Menus/HUD/profile/export screens, routine device QA and manuscript support</td></tr></tbody></table><p>Christian&#39;s path remains a capacity bottleneck. Sherwin now owns the AI and external importer tasks; Miguel executes routine QA with Christian reviewing technical results. Pair or redistribute after the first device spike; adding parallel cards does not eliminate this bottleneck. Reserve time for tests, review and documentation rather than planning all reported 5–8 hours as uninterrupted coding.</p><h2 id="remaining-project-cycle-and-official-manuscript">Remaining project cycle and official manuscript<a class="header-anchor" href="#remaining-project-cycle-and-official-manuscript" aria-label="Link to this section">​</a></h2><p>CH-18–21 retain the broader cycle through April 2027; targets remain subject to actual panel feedback and school confirmation. The user confirmed completed manuscript chapters, functional core modules and pilot-area evidence are mandatory at pre-final. See <a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">the official outline and evidence map</a>. Plan for preliminary and system evaluation evidence; site paperwork and actual results must still be obtained.</p><p>See <a href="/Chainy-Docs/content/docs/team-delegation.html">individual work packets</a> and the <a href="/Chainy-Docs/content/docs/documentation-index.html">full specification</a> before production. Named assignments do not require GitHub accounts. The proposed design review is time-boxed to protect the existing device-spike target.</p><h2 id="october-8-execution-supplement">October 8 execution supplement<a class="header-anchor" href="#october-8-execution-supplement" aria-label="Link to this section">​</a></h2><p>Use the <a href="/Chainy-Docs/content/docs/planning/implementation-plan.html">parallel implementation plan</a> and <a href="/Chainy-Docs/content/docs/planning/agent-task-packets.html">bounded agent packets</a> to dispatch existing tasks. The user confirms no progress or prerequisite updates since October 5 and requests balanced, not identical, commitments. The <a href="/Chainy-Docs/content/docs/team-delegation.html#october-8-workload-balancing-proposal">workload proposal</a> distributes support work without silently changing existing issue Leads, dependencies or dates. CH-01&#39;s October 7 target has passed with completion unverified; resolve it immediately. Original checkpoint dates are retained as history; the following revised forecast supersedes them locally and remains conditional.</p><h2 id="october-8-revised-forecast-tentative-november-36-school-beta">October 8 revised forecast: tentative November 3–6 school beta<a class="header-anchor" href="#october-8-revised-forecast-tentative-november-36-school-beta" aria-label="Link to this section">​</a></h2><p>The user identified <strong>November 3–6 at Tambunan National High School, Marinduque</strong> as a possible beta window. Booking, session duration, participant count, usable device inventory and permissions are unknown. The earlier November 6 integration / November 7 readiness / November 8–13 session sequence cannot support this earlier window. Move the candidate and QA gates forward as follows; original issue due dates, backlog.json and Trello remain unchanged pending deliberate synchronization.</p><table><thead><tr><th>Revised local target</th><th>CH work / predecessor gate</th><th>Required evidence</th></tr></thead><tbody><tr><td>Oct 9–11</td><td>CH-01/02/03/04; CH-01 overdue and unresolved</td><td>Bounded contracts, installed APK and SQLite/relaunch/export proof; missing rubric details recorded explicitly</td></tr><tr><td>Oct 12</td><td>CH-24 after CH-01</td><td>Confirm tentative school contact, booking path, devices, travel and required site documents</td></tr><tr><td>Oct 16–18</td><td>CH-05/26 then CH-06; CH-08; CH-12 after CH-01/02/23/24</td><td>Accepted Level 1 device loop, classifier fixtures, usable protocol/instruments or explicit blocker</td></tr><tr><td>Oct 25</td><td>CH-07/10/11 after original blockers</td><td>Bounded tamper/replica activity, reusable assets, duplicate-safe export/import</td></tr><tr><td>Oct 28</td><td>CH-09 after CH-05/08 (previous target Nov 1)</td><td>AI learning and short agent activity integrated in an isolated scene</td></tr><tr><td>Oct 30</td><td>CH-13 after CH-07/09/10/11/26 (previous Nov 6)</td><td>Integrated three-level beta candidate; feature freeze; identified build/content versions</td></tr><tr><td>Oct 31–Nov 2</td><td>CH-14 after CH-13 (previous Nov 7)</td><td>Real-device offline/save/export/update checks; no unresolved core-blocking or data-loss issue; readiness disposition</td></tr><tr><td>Nov 3–6, tentative</td><td>CH-15 after CH-12/14 (previous finish Nov 13)</td><td>Approved school sessions and actual evidence only if booking and readiness gates pass</td></tr><tr><td>Nov 7–13</td><td>CH-15 evidence cleanup; CH-25 analysis after CH-15/23; bounded fixes/regression</td><td>Validated exports, actual results and defect disposition; no assumed repeat learner session</td></tr><tr><td>Nov 16</td><td>CH-16/25 after original blockers</td><td>Complete manuscript and evidence package using actual collected results</td></tr><tr><td>Nov 17–20</td><td>CH-17 after CH-14/15/16</td><td>Offline rehearsal, critical fixes only, demonstration and recovery kit</td></tr><tr><td>Nov 21</td><td>Confirmed pre-final defense</td><td>Functional core modules, completed manuscript and necessary pilot-area evidence</td></tr></tbody></table><p>Integrate Level 1 by October 18, then merge reviewed module increments October 22, 25 and 28 so October 30 is a candidate gate rather than the first combined build. Christian owns integration; Miguel executes regression; other authors repair their owned modules. Sean prepares results structures before sessions but writes findings only from actual evidence.</p><p>Use the <a href="/Chainy-Docs/content/docs/team-delegation.html#october-8-workload-balancing-proposal">520-hour balanced allocation</a>, including 60 hours of contingency. This is a planning budget with unknown actual availability, not proof that remaining work fits. <strong>Validate first:</strong> if October 11 or 18 gates fail, revise the beta forecast immediately; if October 30 integration or November 2 readiness fails, Sherwin and Sean must resolve the site/adviser implications. Do not consume all QA/rehearsal time, remove required mechanics silently or count internal tests as learner evaluation. The supplied rubric and proposed phone specifications remain unchanged; task counts do not establish 60 percent completion.</p></div>',1)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
